-- PHẦN 1: KHỞI TẠO CƠ SỞ DỮ LIỆU
IF NOT EXISTS (SELECT name FROM sys.databases WHERE name = N'TapHoa36_DB')
BEGIN
    CREATE DATABASE TapHoa36_DB;
    PRINT N'>>> Đã tạo thành công Database [TapHoa36_DB] trên SQL Server 2022/2019!';
END
GO

USE TapHoa36_DB;
GO

SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- XÓA BẢNG CŨ THEO THỨ TỰ PHỤ THUỘC (NẾU ĐÃ TỒN TẠI)
IF OBJECT_ID('dbo.CashflowTransactions', 'U') IS NOT NULL DROP TABLE dbo.CashflowTransactions;
IF OBJECT_ID('dbo.OrderDetails', 'U') IS NOT NULL DROP TABLE dbo.OrderDetails;
IF OBJECT_ID('dbo.Orders', 'U') IS NOT NULL DROP TABLE dbo.Orders;
IF OBJECT_ID('dbo.Products', 'U') IS NOT NULL DROP TABLE dbo.Products;
IF OBJECT_ID('dbo.Categories', 'U') IS NOT NULL DROP TABLE dbo.Categories;
IF OBJECT_ID('dbo.Customers', 'U') IS NOT NULL DROP TABLE dbo.Customers;
IF OBJECT_ID('dbo.Branches', 'U') IS NOT NULL DROP TABLE dbo.Branches;
IF OBJECT_ID('dbo.UsersACL', 'U') IS NOT NULL DROP TABLE dbo.UsersACL;
GO

-- =============================================================================
-- PHẦN 2: THIẾT KẾ CÁC BẢNG QUAN HỆ (TABLE DEFINITIONS)
-- =============================================================================

-- 1. BẢNG CHI NHÁNH & KHO HÀNG (Branches)
CREATE TABLE dbo.Branches (
    branch_id VARCHAR(50) NOT NULL,
    branch_name NVARCHAR(255) NOT NULL,
    address NVARCHAR(500) NOT NULL,
    phone VARCHAR(20) DEFAULT '1900 6522',
    branch_type NVARCHAR(50) DEFAULT N'store',
    is_main BIT DEFAULT 0,
    created_at DATETIME2 DEFAULT SYSDATETIME(),
    CONSTRAINT PK_Branches PRIMARY KEY (branch_id)
);
GO

-- 2. BẢNG NGÀNH HÀNG TIÊU DÙNG (Categories)
CREATE TABLE dbo.Categories (
    category_id VARCHAR(50) NOT NULL,
    category_name NVARCHAR(100) NOT NULL,
    icon_name VARCHAR(50) DEFAULT 'category',
    description NVARCHAR(255) NULL,
    CONSTRAINT PK_Categories PRIMARY KEY (category_id)
);
GO

-- 3. BẢNG HÀNG HÓA & TỒN KHO (Products)
CREATE TABLE dbo.Products (
    product_id VARCHAR(50) NOT NULL,
    barcode VARCHAR(50) NOT NULL,
    product_name NVARCHAR(255) NOT NULL,
    category_id VARCHAR(50) NOT NULL,
    branch_id VARCHAR(50) NOT NULL DEFAULT 'branch_main',
    cost_price DECIMAL(18,2) NOT NULL DEFAULT 0.00,
    price DECIMAL(18,2) NOT NULL,
    stock INT NOT NULL DEFAULT 0,
    unit NVARCHAR(50) DEFAULT N'gói',
    expiry_days INT DEFAULT 90,
    is_active BIT DEFAULT 1,
    created_at DATETIME2 DEFAULT SYSDATETIME(),
    CONSTRAINT PK_Products PRIMARY KEY (product_id),
    CONSTRAINT UQ_Products_Barcode UNIQUE (barcode),
    CONSTRAINT FK_Products_Categories FOREIGN KEY (category_id) REFERENCES dbo.Categories(category_id) ON UPDATE CASCADE,
    CONSTRAINT FK_Products_Branches FOREIGN KEY (branch_id) REFERENCES dbo.Branches(branch_id) ON UPDATE CASCADE
);
GO

-- 4. BẢNG KHÁCH HÀNG & CÔNG NỢ SỔ QUEN (Customers)
CREATE TABLE dbo.Customers (
    customer_id VARCHAR(50) NOT NULL,
    full_name NVARCHAR(150) NOT NULL,
    phone VARCHAR(20) NULL,
    customer_group VARCHAR(50) DEFAULT 'retail',
    debt_amount DECIMAL(18,2) DEFAULT 0.00,
    address NVARCHAR(255) NULL,
    created_at DATETIME2 DEFAULT SYSDATETIME(),
    CONSTRAINT PK_Customers PRIMARY KEY (customer_id),
    CONSTRAINT UQ_Customers_Phone UNIQUE (phone)
);
GO

-- 5. BẢNG HÓA ĐƠN BÁN HÀNG (Orders)
CREATE TABLE dbo.Orders (
    order_id VARCHAR(50) NOT NULL,
    order_code VARCHAR(50) NOT NULL,
    branch_id VARCHAR(50) NOT NULL DEFAULT 'branch_main',
    customer_id VARCHAR(50) NULL,
    total_amount DECIMAL(18,2) NOT NULL,
    discount_amount DECIMAL(18,2) DEFAULT 0.00,
    final_amount DECIMAL(18,2) NOT NULL,
    payment_method VARCHAR(50) NOT NULL DEFAULT 'cash',
    order_status VARCHAR(50) NOT NULL DEFAULT 'completed',
    order_type VARCHAR(50) NOT NULL DEFAULT 'pos',
    created_at DATETIME2 DEFAULT SYSDATETIME(),
    CONSTRAINT PK_Orders PRIMARY KEY (order_id),
    CONSTRAINT UQ_Orders_Code UNIQUE (order_code),
    CONSTRAINT FK_Orders_Branches FOREIGN KEY (branch_id) REFERENCES dbo.Branches(branch_id),
    CONSTRAINT FK_Orders_Customers FOREIGN KEY (customer_id) REFERENCES dbo.Customers(customer_id) ON DELETE SET NULL
);
GO

-- 6. BẢNG CHI TIẾT HÓA ĐƠN (OrderDetails)
CREATE TABLE dbo.OrderDetails (
    detail_id INT IDENTITY(1,1) NOT NULL,
    order_id VARCHAR(50) NOT NULL,
    product_id VARCHAR(50) NOT NULL,
    quantity INT NOT NULL DEFAULT 1,
    unit_price DECIMAL(18,2) NOT NULL,
    subtotal AS (quantity * unit_price) PERSISTED,
    CONSTRAINT PK_OrderDetails PRIMARY KEY (detail_id),
    CONSTRAINT FK_OrderDetails_Orders FOREIGN KEY (order_id) REFERENCES dbo.Orders(order_id) ON DELETE CASCADE,
    CONSTRAINT FK_OrderDetails_Products FOREIGN KEY (product_id) REFERENCES dbo.Products(product_id)
);
GO

-- 7. BẢNG SỔ QUỸ & DÒNG TIỀN (CashflowTransactions)
CREATE TABLE dbo.CashflowTransactions (
    trans_id VARCHAR(50) NOT NULL,
    trans_type VARCHAR(20) NOT NULL,
    amount DECIMAL(18,2) NOT NULL,
    category_name NVARCHAR(100) NOT NULL,
    note NVARCHAR(255) NULL,
    branch_id VARCHAR(50) NOT NULL DEFAULT 'branch_main',
    created_at DATETIME2 DEFAULT SYSDATETIME(),
    CONSTRAINT PK_Cashflow PRIMARY KEY (trans_id),
    CONSTRAINT FK_Cashflow_Branches FOREIGN KEY (branch_id) REFERENCES dbo.Branches(branch_id)
);
GO

-- 8. BẢNG PHÂN QUYỀN TÀI KHOẢN (UsersACL)
CREATE TABLE dbo.UsersACL (
    user_id VARCHAR(50) NOT NULL,
    username VARCHAR(50) NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    full_name NVARCHAR(100) NOT NULL,
    user_role VARCHAR(50) NOT NULL,
    is_active BIT DEFAULT 1,
    created_at DATETIME2 DEFAULT SYSDATETIME(),
    CONSTRAINT PK_UsersACL PRIMARY KEY (user_id),
    CONSTRAINT UQ_UsersACL_Username UNIQUE (username)
);
GO

