-- =============================================================================
-- PHẦN 4: CÁC CÂU LỆNH TRUY VẤN MẪU HAY ĐƯỢC HỎI KHI VẤN ĐÁP THI (SSMS)
-- =============================================================================

-- Câu 1: Xem toàn bộ danh sách sản phẩm kèm tên ngành hàng
SELECT TOP 20 p.barcode AS [Mã Vạch], p.product_name AS [Tên Sản Phẩm], c.category_name AS [Ngành Hàng], 
       p.price AS [Giá Bán (VNĐ)], p.stock AS [Tồn Kho], p.unit AS [ĐVT]
FROM dbo.Products p
JOIN dbo.Categories c ON p.category_id = c.category_id
ORDER BY p.stock ASC;
GO

-- Câu 2: Thống kê tổng doanh thu bán lẻ thực thu theo phương thức thanh toán
SELECT payment_method AS [Phương Thức], COUNT(*) AS [Số Lượng Đơn], 
       SUM(final_amount) AS [Tổng Doanh Thu (VNĐ)]
FROM dbo.Orders
GROUP BY payment_method;
GO

-- Câu 3: Báo cáo danh sách khách hàng còn dư nợ sổ quen để thu hồi
SELECT full_name AS [Khách Hàng], phone AS [SĐT], debt_amount AS [Số Tiền Nợ (VNĐ)], address AS [Địa Chỉ]
FROM dbo.Customers
WHERE debt_amount > 0
ORDER BY debt_amount DESC;
GO

-- Câu 4: Top sản phẩm bán chạy nhất tiệm
SELECT TOP 5 p.product_name AS [Tên Hàng], SUM(od.quantity) AS [Tổng Số Đã Bán], SUM(od.subtotal) AS [Doanh Số (VNĐ)]
FROM dbo.OrderDetails od
JOIN dbo.Products p ON od.product_id = p.product_id
GROUP BY p.product_name
ORDER BY [Tổng Số Đã Bán] DESC;
GO

